import RNA, random, time
target = ".....((((.(((.((....))((....)).))).(((.((....))((....)).))).(((.((....))((....)).))).(((.((....))((....)).))).))))....."
def dist(s): return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], target)

stack=[]; pairs=set()
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')': pairs.add((stack.pop(),i))
paired=set([i for p in pairs for i in p])

def assign(seed):
    r=random.Random(seed)
    out=['A']*len(target)
    for (i,j) in pairs:
        p=r.choice(['GC','CG','AU','UA','GC','CG','GC','CG'])
        out[i]=p[0]; out[j]=p[1]
    for a,b in [[16,19],[24,27],[41,44],[49,52],[66,69],[74,77],[91,94],[99,102]]:
        out[a]='G'; out[a+1]='A'; out[a+2]='A'; out[a+3]='A'
    return ''.join(out)

# SA from a good init
def run(seed, deadline):
    cur=assign(seed); cur_d=dist(cur)
    best,best_d=cur,cur_d
    r=random.Random(seed+999)
    while time.time()<deadline and best_d>0:
        c=list(cur)
        k=r.choice([1,1,1,2,3])
        for _ in range(k):
            i=r.randrange(len(c))
            if i in paired:
                # mutate but keep pair? no, random for now
                c[i]=r.choice('ACGU')
            else:
                c[i]=r.choice('ACGU')
        c=''.join(c); d=dist(c)
        if d<cur_d or (d==cur_d and r.random()<0.4):
            cur,cur_d=c,d
            if d<best_d: best,best_d=c,d
    return best_d,best

deadline=time.time()+100
bd,bs=run(11, deadline)
print("final", bd, bs)
