import RNA, random, time, multiprocessing as mp
target = ".....((((.(((.((....))((....)).))).(((.((....))((....)).))).(((.((....))((....)).))).(((.((....))((....)).))).))))....."
def fold(s): return RNA.fold_compound(s).mfe()[0]
def dist(s): return RNA.bp_distance(fold(s), target)

def worker(seed):
    r=random.Random(seed)
    for _ in range(50):
        start=''.join(r.choice('ACGU') for _ in range(len(target)))
        seq,d=RNA.inverse_fold(start,target)
        if d==0:
            st=fold(seq)
            if st==target:
                return seq
    return None

if __name__=='__main__':
    t0=time.time()
    with mp.Pool(64) as p:
        for r in p.imap_unordered(worker, range(1280)):
            if r:
                print("SOLVED", r); p.terminate(); break
    print("elapsed", time.time()-t0)
